+import React, { useState } from 'react';
+import { Card, CardContent, CardHeader } from '@/components/ui/card';
+import { MetricsCollector } from '@anthropic-ai/telemetry-sdk';
+import { useAutoRefresh, useQueryClient } from '@tanstack/react-query';
+import { formatCurrency } from '../utils/format';
+
+interface TeamMetrics {
+  teamId: string;
+  teamName: string;
+  tokensUsed: number;
+  costUsd: number;
+  requestCount: number;
+}
+
+const collector = new MetricsCollector({
+  apiKey: process.env.ANTHROPIC_API_KEY,
+  flushInterval: 5000,
+});
+
+export function MetricsDashboard() {
+  const [metrics, setMetrics] = useState<TeamMetrics[]>([]);
+  const queryClient = useQueryClient();
+
+  // Auto-refresh metrics every 30 seconds
+  useAutoRefresh({
+    interval: 30_000,
+    onRefresh: async () => {
+      const data = await collector.fetchTeamMetrics();
+      setMetrics(data);
+      queryClient.invalidateQueries({ queryKey: ['metrics'] });
+    },
+  });
+
+  const totalCost = metrics.reduce((sum, m) => sum + m.costUsd, 0);
+
+  return (
+    <div className="grid grid-cols-3 gap-4">
+      <Card>
+        <CardHeader>Total Cost (MTD)</CardHeader>
+        <CardContent>{formatCurrency(totalCost)}</CardContent>
+      </Card>
+      {metrics.map((m) => (
+        <Card key={m.teamId}>
+          <CardHeader>{m.teamName}</CardHeader>
+          <CardContent>
+            <p>{m.tokensUsed.toLocaleString()} tokens</p>
+            <p>{formatCurrency(m.costUsd)}</p>
+          </CardContent>
+        </Card>
+      ))}
+    </div>
+  );
+}

